import java.nio.file.*;
import java.io.IOException;
import java.util.List;

public class FileTasks {
    public List<String> readLines(Path path) {
        try {
            if (!Files.exists(path)) return List.of();
            return Files.readAllLines(path);
        } catch (IOException e) {
            return List.of();
        }
    }
}

